const billInput = document.getElementById('bill');
const tipInput = document.getElementById('tip-percent');
const tipOut = document.getElementById('tip-amount');
const totalOut = document.getElementById('total-amount');

function format(n) {
  return `$${n.toFixed(2)}`;
}

function recalculate() {
  const bill = parseFloat(billInput.value) || 0;
  const percent = parseFloat(tipInput.value) || 0;
  const tip = bill * (percent / 100);
  const total = bill + tip;
  tipOut.textContent = format(tip);
  totalOut.textContent = format(total);
}

billInput.addEventListener('input', recalculate);
tipInput.addEventListener('input', recalculate);
recalculate();
